request.description:
Public. controller: category.controller.ts:getAllCategories. Returns all categories ordered by id ASC.
200 -> { success:true, data:[{id,name,slug}], statusCode:200 }
Also available as /api/v1/categories

Public. category.controller.ts:getCategoryBySlug. Lookup by unique slug (e.g. dresses, bags).
200 -> { success:true, data:{id,name,slug} }
404 if not found.

body.raw:
{
  "name": "Shoes",
  "slug": "shoes"
}
// name required 2-100 chars, trimmed
// slug optional 2-120 chars; if omitted auto-generated from name via slugify() (e.g. "Evening Dresses" -> "evening-dresses")
// slug may contain letters (including Arabic), numbers, hyphens only
// Examples:
// { "name": "Shoes" }
// { "name": "Evening Dresses", "slug": "evening-dresses" }
// { "name": "أحذية" } -> slug auto "أحذية"

{
  "name": "Evening Dresses",
  "slug": "evening-dresses"
}
// At least one of name or slug required
// If only name provided, slug auto-regenerates from new name
// If slug provided explicitly, it is normalized via slugify()
// Examples:
// { "name": "Updated Name" }
// { "slug": "custom-slug" }
// { "name": "New Name", "slug": "custom-slug" }

request.description:
Public. product.controller.ts:getAllProducts. Returns all products with relations colors/sizes/images/category ordered by id ASC.
200 -> { success:true, data:[{id,name,categoryId,price,oldPrice,tag,defaultShape,shortDescription,isActive,mainImageUrl,createdAt, colors:[{id,nameEn,nameAr,hexCode}], sizes:[{id,size,isAvailable}], images:[{id,imageUrl,sortOrder}], category:{id,name,slug}}], statusCode:200 }
Also available as /api/v1/products

body.raw:
{
  "name": "Puff Sleeve Dress",
  "categoryId": 1,
  "price": 1299,
  "oldPrice": 1599,
  "tag": "new",
  "defaultShape": "puff_sleeves",
  "shortDescription": "Demo dress - puff sleeves default shape",
  "isActive": true,
  "mainImageUrl": "/uploads/demo.jpg",
  "colors": [1, 2],
  "sizes": [
    { "size": "S", "isAvailable": true },
    { "size": "M", "isAvailable": true },
    { "size": "L", "isAvailable": false }
  ],
  "images": [
    { "imageUrl": "/uploads/demo.jpg", "sortOrder": 0 }
  ]
}
// JSON variant — best for testing logic without files. Al Rouba: media[].order as main (0 = main), normalized contiguous.
// Required: name 2-200, categoryId|categorySlug, price, colors [IDs], sizes [S|M|L|XL]
// Optional: oldPrice, tag none|new|best_seller, defaultShape, shortDescription, isActive, mainImageUrl (if omitted, auto-set to first image order 0 like Al Rouba), images [{imageUrl, sortOrder}]
// colors: [1,2] palette IDs cloned via In() — no DB change — see product.controller.ts:80
// For multipart file upload, use the next request (POST multipart). JSON + multipart both normalized to contiguous sortOrder.

{
  "currentOrder": 2,
  "newOrder": 0
}
// Moves image from order 2 to order 0 — shifts intervening items like Al Rouba reorderMedia.
// After reorder, mainImageUrl auto-updated to new order 0 image.
